"""
Flask API server — the main web serving layer for Beyond the Stats.

Architecture
------------
This is a single Flask application that serves all REST API endpoints plus the
static frontend. It runs inside gunicorn (production, Steam Deck) or the Flask
dev server (local). A background thread (``_live_score_poller_loop``) polls ESPN
for live scores/summaries every ~60s and stores them in in-memory dicts. The
pipeline (data download → model training → prediction) runs as a subprocess
triggered either by a scheduler in ``Backend/server.py`` or manually via the
``/api/refresh`` endpoint.

Key subsystems (in order of appearance)
----------------------------------------
1. **Constants & config**          — ESPN competition IDs, file paths, cache TTLs
2. **Live-score polling**          — Background thread, ESPN API, summary cache
3. **Standings / leaders**         — Real league tables & stat leaders from ESPN
4. **Pre-match prediction loading**— Reads CSV files generated by the pipeline.
5. **REST API endpoints**          — All ``/api/*`` routes (32+ endpoints)
6. **Entry point**                 — ``start_live_score_poller()`` + ``app.run()``

Thread safety
-------------
``_live_scores`` and ``_live_summary_cache`` are module-level dicts accessed by
both the background poller and the API request handlers. Guarded by reentrant
locks (``RLock`` / ``Lock``). The poller also has a day‑boundary clear at
midnight ET.
"""
