def _valid_date_iso(s):
    """Return True if s matches YYYY-MM-DD (ISO 8601 date)."""
    return bool(re.fullmatch(r"\d{4}-\d{2}-\d{2}", s))


@app.get("/api/live-score-history")
def api_live_score_history():
    """Return historical completed games, grouped by competition
    (matching ``/api/live-scores`` response structure).

    Query params:
        league   -- filter by competition name (substring match, case-insensitive)
        from     -- start date (ISO, e.g. 2026-06-01), filters by kickoff_utc >=
        to       -- end date (ISO, e.g. 2026-06-18), filters by kickoff_utc <=
    """
    league = request.args.get("league", "").strip()
    from_date = request.args.get("from", "").strip()
    to_date = request.args.get("to", "").strip()

    # Validate date format
    if from_date and not _valid_date_iso(from_date):
        return jsonify({"ok": False, "error": "Invalid 'from' date format (use YYYY-MM-DD)"}), 400
    if to_date and not _valid_date_iso(to_date):
        return jsonify({"ok": False, "error": "Invalid 'to' date format (use YYYY-MM-DD)"}), 400

    games = _load_live_score_history()

    if league:
        league_lower = league.lower()
        games = [g for g in games if league_lower in g.get("competition", "").lower()]
    if from_date:
        games = [g for g in games if g.get("kickoff_utc", "") >= from_date]
    if to_date:
        games = [g for g in games if g.get("kickoff_utc", "") <= to_date]

    games.sort(key=lambda g: g.get("kickoff_utc", ""), reverse=True)

    competitions = {}
    for g in games:
        comp = g.get("competition", "Unknown")
        if comp not in competitions:
            competitions[comp] = {
                "competition": comp,
                "games": [],
                "last_polled_utc": datetime.now(timezone.utc).isoformat(),
            }
        competitions[comp]["games"].append(g)

    return jsonify({
        "ok": True,
        "competitions": competitions,
    })



def _compute_goal_eq(lam, k):
    """P(home goals == k) via Poisson."""
    lam = max(0.01, _safe_float(lam, 0.0))
    return _poisson_pmf(k, lam)


def _compute_goal_ge(lam, k):
    """P(home goals >= k) via Poisson."""
    lam = max(0.01, _safe_float(lam, 0.0))
    return 1.0 - sum(_poisson_pmf(i, lam) for i in range(k)) if k > 0 else 1.0


def _compute_both_score(lam_h, lam_a):
    """P(both teams score) via independent Poisson."""
    hg = max(0.01, _safe_float(lam_h, 0.0))
    ag = max(0.01, _safe_float(lam_a, 0.0))
    return (1.0 - math.exp(-hg)) * (1.0 - math.exp(-ag))


def _compute_total_ge(lam_h, lam_a, threshold):
    """P(total goals >= threshold) via Poisson of sum."""
    hg = max(0.01, _safe_float(lam_h, 0.0))
    ag = max(0.01, _safe_float(lam_a, 0.0))
    lam = hg + ag
    return 1.0 - sum(_poisson_pmf(i, lam) for i in range(int(threshold)))


def _enrich_json_past_row(r):
    """Add display fields to a raw past_games.json row so it matches upcoming format."""
    pred = str(r.get("predicted_result", "")).strip().upper()
    home = str(r.get("home_team", "")).strip()
    away = str(r.get("away_team", "")).strip()
    r["winner_label"] = (
        f"Pred: {home}" if pred == "H" else
        f"Pred: {away}" if pred == "A" else
        "Pred: Draw" if pred == "D" else ""
    )
    actual = str(r.get("actual_result", "")).strip().upper()
    if actual in {"H", "D", "A"}:
        r["is_correct"] = "1" if pred == actual else "0"
    else:
        r["is_correct"] = ""

    try:
        ph = float(r.get("prob_home", 0) or 0) * 100
        pdv = float(r.get("prob_draw", 0) or 0) * 100
        pa = float(r.get("prob_away", 0) or 0) * 100
    except Exception:
        ph = pdv = pa = 0.0
    r["prob_home_text"] = _format_percent_value(ph)
    r["prob_draw_text"] = _format_percent_value(pdv)
    r["prob_away_text"] = _format_percent_value(pa)

    md = str(r.get("match_date", "")).strip()
    if md:
        try:
            dt = pd.to_datetime(md, errors="coerce")
            if pd.notna(dt):
                r["weekday"] = dt.strftime("%A")
                r["date_label"] = dt.strftime("%B %d, %Y")
        except Exception:
            r["weekday"] = ""
            r["date_label"] = md
    else:
        r["weekday"] = ""
        r["date_label"] = ""

    utc_dt = str(r.get("match_datetime_utc", "")).strip()
    if utc_dt:
        try:
            dt = pd.to_datetime(utc_dt, utc=True, errors="coerce")
            if pd.notna(dt):
                dt = dt.tz_convert("America/New_York")
                r["match_datetime_et"] = dt.strftime("%Y-%m-%dT%H:%M:%S%z")
                r["time_label"] = dt.strftime("%I:%M %p ET").lstrip("0")
        except Exception:
            pass
    if "time_label" not in r:
        r["time_label"] = ""

    # Normalize score fields
    for score_key in ("actual_home_goals", "actual_away_goals", "home_score", "away_score"):
        v = r.get(score_key)
        if v is not None:
            try:
                r[score_key] = int(float(v))
            except (ValueError, TypeError):
                pass

    # Map home_score → actual_home_goals and vice versa
    if r.get("home_score") is not None and r.get("actual_home_goals") is None:
        r["actual_home_goals"] = r["home_score"]
    if r.get("away_score") is not None and r.get("actual_away_goals") is None:
        r["actual_away_goals"] = r["away_score"]
    if r.get("actual_home_goals") is not None and r.get("home_score") is None:
        r["home_score"] = r["actual_home_goals"]
    if r.get("actual_away_goals") is not None and r.get("away_score") is None:
        r["away_score"] = r["actual_away_goals"]


def _is_placeholder_game(r):
    """Return True if a game dict is a placeholder (not a real match)."""
    for key in ("home_team", "away_team"):
        val = str(r.get(key, "")).lower()
        if "group" in val or "third place" in val or "winner" in val or "runner" in val:
            return True
    return False


def _week_based_cutoff():
    """Return ISO date string for the start of the previous full week (Mon)."""
    today_local = datetime.now(ZoneInfo("America/New_York")).date()
    current_week_start = today_local - timedelta(days=today_local.weekday())
    return (current_week_start - timedelta(days=7)).isoformat()


@app.get("/api/past-games")
@_cached_response(ttl=CACHE_TTL_DEFAULT)
def api_past_games():
    """Return completed games persisted across pipeline runs.

    Response structure matches ``/api/upcoming/global`` per-row format.

    Data is sourced from ``past_games.json`` (the persistent archive) and
    supplemented with any recently completed rows from the prediction CSVs
    that haven't been archived yet.  Rows older than the previous full week
    are excluded.

    For full live-score details (lineups, stats, key events, game info),
    use ``/api/live-score-history``.

    Query params:
        league   -- filter by competition name (substring match, case-insensitive)
        page     -- page number (default 1)
        per_page -- results per page (default 50, max 200)
    """
    league = request.args.get("league", "").strip()
    try:
        page = max(1, int(request.args.get("page", "1")))
    except (ValueError, TypeError):
        page = 1
    try:
        per_page = min(200, max(1, int(request.args.get("per_page", "50"))))
    except (ValueError, TypeError):
        per_page = 50

    cutoff = _week_based_cutoff()

    # ── 1. Rows from persistent archive ────────────────────────────
    by_key = {}
    archive = _load_json_payload(PAST_GAMES_FILE)
    if isinstance(archive, list):
        for r in archive:
            if str(r.get("match_date", "")).strip() < cutoff:
                continue
            if _is_placeholder_game(r):
                continue
            _enrich_json_past_row(r)
            ck = "|".join(str(r.get(k, "")).strip().lower() for k in ("match_date", "competition", "home_team", "away_team"))
            if ck:
                by_key[ck] = r

    # ── 2. Supplement with CSV rows (richer data) ──────────────────
    for source, csv_path in (
        ("global", GLOBAL_UPCOMING_FILE),
        ("mls", MLS_UPCOMING_FILE),
        ("extra", EXTRA_UPCOMING_FILE),
        ("cups", CUP_UPCOMING_FILE),
        ("national", NATIONAL_UPCOMING_FILE),
    ):
        rows, _st, _ls = _load_upcoming_rows(csv_path, source, date_range="completed")
        for r in rows:
            if str(r.get("match_date", "")).strip() < cutoff:
                continue
            # Only include actually settled games — skip placeholders
            if str(r.get("actual_result", "")).strip().upper() not in {"H", "D", "A"}:
                continue
            if _is_placeholder_game(r):
                continue
            ck = "|".join(str(r.get(k, "")).strip().lower() for k in ("match_date", "competition", "home_team", "away_team"))
            if ck:
                by_key[ck] = r  # CSV row (enriched) takes priority

    all_rows = list(by_key.values())

    if league:
        league_lower = league.lower()
        all_rows = [r for r in all_rows if league_lower in r.get("competition", "").lower()]

    all_rows.sort(key=lambda r: r.get("match_date", ""), reverse=True)

    total = len(all_rows)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = all_rows[start:end]

    return jsonify({
        "ok": True,
        "rows": page_rows,
        "total": total,
        "page": page,
        "per_page": per_page,
        "date_window": {
            "from": cutoff,
            "to": datetime.now(ZoneInfo("America/New_York")).date().isoformat(),
        },
    })


@app.get("/api/cup-bracket")
@_cached_response(ttl=CACHE_TTL_LONG)
def api_cup_bracket():
    """Return real bracket for a cup competition in World Cup format.

    Response mirrors ``/api/world-cup``:

    * ``knockout`` — ``{stage_key: [matches]}}`` with actual winners
      from live scores / projected bracket.
    * ``odds_knockout`` — same topology, each match's ``winner`` is the
      team with higher ``prob_home`` / ``prob_away``.
    * ``real_knockout`` — winners only from completed (``post``) games;
      unplayed matches show both teams but ``winner: null``.

    Additional cup-specific fields:
    ``knockout_rounds`` (bracket topology with feeds_to),
    ``league_phase`` (UEFA league-phase table),
    ``cup_format`` (format descriptor).

    Query params:
        competition  -- required, e.g. "England/FA Cup", "FIFA/World Cup",
                        "UEFA/Champions League"
    """
    comp = request.args.get("competition", "").strip()
    if not comp:
        return jsonify({"ok": False, "error": "Missing 'competition' parameter"}), 400
    if comp not in LIVE_SCORE_COMPETITIONS:
        return jsonify({"ok": False, "error": f"Unknown competition: {comp}"}), 400

    matches = []

    # 1. Completed games from live score history
    history = _load_live_score_history()
    seen_ids = set()
    for g in history:
        if g.get("competition") == comp:
            mid = g.get("match_id", "")
            if mid:
                seen_ids.add(mid)
            matches.append(g)

    # 2. In-progress / finished today from live scores
    with _live_scores_lock:
        current = _live_scores.get(comp, {}).get("games", [])
    for g in current:
        mid = g.get("match_id", "")
        if mid not in seen_ids:
            if mid:
                seen_ids.add(mid)
            matches.append(g)

    # 3. Upcoming games from the projected cup bracket JSON
    bracket_data = _load_json_payload(CUP_PROJECTED_BRACKET_FILE)
    if isinstance(bracket_data, dict):
        comp_entry = bracket_data.get(comp)
        if isinstance(comp_entry, dict):
            for round_name, round_matches in comp_entry.items():
                if isinstance(round_matches, list):
                    for entry in round_matches:
                        if not isinstance(entry, dict):
                            continue
                        hm = str(entry.get("home_team", "") or "")
                        aw = str(entry.get("away_team", "") or "")
                        if not hm or not aw:
                            continue
                        matches.append({
                            "home_team": hm,
                            "away_team": aw,
                            "home_score": None,
                            "away_score": None,
                            "status": "pre",
                            "kickoff_utc": _utc_to_et(str(entry.get("match_datetime_utc", "") or "")),
                            "round": round_name,
                            "competition": comp,
                            "match_id": str(entry.get("match_id", "") or ""),
                        })

    # 4. Enrich with odds from cup predictions CSV
    odds_index = {}
    try:
        odds_df = pd.read_csv(CUP_UPCOMING_FILE)
        if not odds_df.empty and all(c in odds_df.columns for c in ("home_team", "away_team", "prob_home", "prob_draw", "prob_away")):
            for _, row in odds_df.iterrows():
                key = (str(row["home_team"]).strip().lower(), str(row["away_team"]).strip().lower())
                odds_index[key] = {
                    "prob_home": _safe_float(row["prob_home"], None),
                    "prob_draw": _safe_float(row["prob_draw"], None),
                    "prob_away": _safe_float(row["prob_away"], None),
                }
    except Exception:
        pass

    for g in matches:
        rnd = g.get("round", "") or "Match"
        order = g.get("round_order", 0)
        if not isinstance(order, (int, float)):
            try:
                order = int(order)
            except (ValueError, TypeError):
                order = 0
        g["round_order"] = order
        g["round"] = rnd

        # Compute winner for completed games
        if g.get("status") == "post":
            hs = g.get("home_score")
            aws = g.get("away_score")
            if hs is not None and aws is not None:
                if hs > aws:
                    g["winner"] = g.get("home_team", "")
                elif aws > hs:
                    g["winner"] = g.get("away_team", "")

        # Attach odds
        hm_name = str(g.get("home_team", "")).strip().lower()
        aw_name = str(g.get("away_team", "")).strip().lower()
        odds = odds_index.get((hm_name, aw_name)) or odds_index.get((aw_name, hm_name), {})
        g["prob_home"] = odds.get("prob_home")
        g["prob_draw"] = odds.get("prob_draw")
        g["prob_away"] = odds.get("prob_away")

    # 5. Build WC-style knockout structures
    knockout, odds_knockout, real_knockout = _build_knockout_wc_format(matches)

    result = {
        "ok": True,
        "competition": comp,
        "knockout": knockout,
        "odds_knockout": odds_knockout,
        "real_knockout": real_knockout,
    }
    ko_framework = _build_knockout_framework(comp)
    if ko_framework:
        result["knockout_rounds"] = ko_framework
    if comp in _UEFA_COMPETITIONS:
        league_table = _compute_standings_from_history(comp)
        if league_table:
            result["league_phase"] = league_table
    cup_format = _CUP_FORMATS.get(comp)
    if cup_format:
        result["cup_format"] = cup_format

    return jsonify(result)


@app.get("/api/real-cup-data")
def api_real_cup_data():
    """Return real cup data in World Cup format.

    Response mirrors ``/api/world-cup``:

    * ``knockout`` — ``{stage_key: [matches]}}`` with actual winners
      from live scores / projected bracket.
    * ``odds_knockout`` — same topology, each match's ``winner`` is the
      team with higher ``prob_home`` / ``prob_away``.
    * ``real_knockout`` — winners only from completed (``post``) games.

    Additional fields: ``cup_format``, ``table``, ``knockout_rounds``.

    Query params:
        competition  -- required, e.g. "UEFA/Champions League", "England/FA Cup"
    """
    comp = request.args.get("competition", "").strip()
    if not comp:
        return jsonify({"ok": False, "error": "Missing 'competition' parameter"}), 400
    if comp not in LIVE_SCORE_COMPETITIONS:
        return jsonify({"ok": False, "error": f"Unknown competition: {comp}"}), 400

    # 1. Format metadata
    cup_format = _CUP_FORMATS.get(comp)
    if comp in _UEFA_COMPETITIONS and cup_format is None:
        for key, fmt in _CUP_FORMATS.items():
            if key in _UEFA_COMPETITIONS and LIVE_SCORE_COMPETITIONS.get(comp) == LIVE_SCORE_COMPETITIONS.get(key):
                cup_format = fmt
                break

    # 2. Group / league phase tables from history
    table = _compute_standings_from_history(comp)

    # 3. Gather all matches for this competition
    matches = []
    history = _load_live_score_history()
    seen_ids = set()
    for g in history:
        if g.get("competition") == comp:
            mid = g.get("match_id", "")
            if mid:
                seen_ids.add(mid)
            matches.append(g)

    with _live_scores_lock:
        current = _live_scores.get(comp, {}).get("games", [])
    for g in current:
        mid = g.get("match_id", "")
        if mid not in seen_ids:
            if mid:
                seen_ids.add(mid)
            matches.append(g)

    # Upcoming matchups from projected cup bracket
    bracket_data = _load_json_payload(CUP_PROJECTED_BRACKET_FILE)
    if isinstance(bracket_data, dict):
        comp_entry = bracket_data.get(comp)
        if isinstance(comp_entry, dict):
            for round_name, round_matches in comp_entry.items():
                if isinstance(round_matches, list):
                    for entry in round_matches:
                        if not isinstance(entry, dict):
                            continue
                        hm = str(entry.get("home_team", "") or "")
                        aw = str(entry.get("away_team", "") or "")
                        if not hm or not aw:
                            continue
                        matches.append({
                            "home_team": hm,
                            "away_team": aw,
                            "home_score": None,
                            "away_score": None,
                            "status": "pre",
                            "kickoff_utc": _utc_to_et(str(entry.get("match_datetime_utc", "") or "")),
                            "round": round_name,
                            "competition": comp,
                            "match_id": str(entry.get("match_id", "") or ""),
                        })

    # 4. Enrich with odds and round metadata
    odds_index = {}
    try:
        odds_df = pd.read_csv(CUP_UPCOMING_FILE)
        if not odds_df.empty and all(c in odds_df.columns for c in ("home_team", "away_team", "prob_home", "prob_draw", "prob_away")):
            for _, row in odds_df.iterrows():
                key = (str(row["home_team"]).strip().lower(), str(row["away_team"]).strip().lower())
                odds_index[key] = {
                    "prob_home": _safe_float(row["prob_home"], None),
                    "prob_draw": _safe_float(row["prob_draw"], None),
                    "prob_away": _safe_float(row["prob_away"], None),
                }
    except Exception:
        pass

    for g in matches:
        rnd = g.get("round", "") or "Match"
        order = g.get("round_order", 0)
        if not isinstance(order, (int, float)):
            try:
                order = int(order)
            except (ValueError, TypeError):
                order = 0
        g["round_order"] = order
        g["round"] = rnd

        # Compute winner for completed games
        if g.get("status") == "post":
            hs = g.get("home_score")
            aws = g.get("away_score")
            if hs is not None and aws is not None:
                if hs > aws:
                    g["winner"] = g.get("home_team", "")
                elif aws > hs:
                    g["winner"] = g.get("away_team", "")

        # Attach odds
        hm_name = str(g.get("home_team", "")).strip().lower()
        aw_name = str(g.get("away_team", "")).strip().lower()
        odds = odds_index.get((hm_name, aw_name)) or odds_index.get((aw_name, hm_name), {})
        g["prob_home"] = odds.get("prob_home")
        g["prob_draw"] = odds.get("prob_draw")
        g["prob_away"] = odds.get("prob_away")

    # 5. Build WC-style knockout structures
    knockout, odds_knockout, real_knockout = _build_knockout_wc_format(matches)

    result = {
        "ok": True,
        "competition": comp,
        "cup_format": cup_format,
        "knockout": knockout,
        "odds_knockout": odds_knockout,
        "real_knockout": real_knockout,
    }

    ko_framework = _build_knockout_framework(comp)
    if ko_framework:
        result["knockout_rounds"] = ko_framework

    if table is not None:
        result["table"] = table

    return jsonify(result)


def _fill_placeholder_tables(data):
    """Fill ``data["tables"]`` with zero-stat team entries from league_teams.json
    for any competition in ``data["leagues"]`` that has no projected table data.

    Mutates ``data["tables"]`` in place.
    """
    league_teams = _load_league_teams()
    tables = data.get("tables", {})
    leagues = data.get("leagues", [])
    now_utc = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
    for comp_name in leagues:
        if comp_name in tables and tables[comp_name]:
            continue
        roster = league_teams.get(comp_name)
        if not roster:
            continue
        entries = []
        for pos, team in enumerate(sorted(roster), start=1):
            entries.append({
                "position": pos, "team": team,
                "P": 0, "W": 0, "D": 0, "L": 0,
                "GF": 0, "GA": 0, "GD": 0, "Pts": 0,
                "PlayedReal": 0, "PlayedPred": 0,
                "win_league_pct": 0.0, "top4_pct": 0.0, "bottom3_pct": 0.0,
                "most_likely_position": 0, "most_likely_position_pct": 0.0,
                "position_odds": {}, "sim_runs": 0,
            })
        tables[comp_name] = entries
    data["tables"] = tables


def _build_fallback_standings(comp_name):
    """Return a placeholder standings dict with all known teams on 0 points.

    Reads every upcoming prediction CSV source (including ``Output/`` dirs)
    and projected table CSVs for *comp_name* and returns teams sorted
    alphabetically.  If no teams are found, returns ``None``.

    Does NOT call ESPN API — teams are discovered from local CSV data only.

    Response shape (matches ``_compute_standings_from_history``):
    ``{"competition": str, "groups": [{"name": "Overall", "entries": [...]}]}``
    """
    teams = set()

    # 1. Persisted league-team rosters (offseason fallback from fetch_league_teams.py)
    league_teams = _load_league_teams()
    cached = league_teams.get(comp_name)
    if cached:
        teams.update(cached)

    # 2. Upcoming prediction CSVs and projected table CSVs
    csv_sources = [
        GLOBAL_UPCOMING_FILE,
        MLS_UPCOMING_FILE,
        EXTRA_UPCOMING_FILE,
        CUP_UPCOMING_FILE,
        NATIONAL_UPCOMING_FILE,
        os.path.join(PROJECT_DIR, "Output", "Upcoming", "all_upcoming.csv"),
        os.path.join(PROJECT_DIR, "Output", "Europe", "Upcoming", "europe_upcoming.csv"),
        os.path.join(PROJECT_DIR, "Output", "National", "Upcoming", "national_upcoming.csv"),
        GLOBAL_PROJECTED_TABLE_FILE,
        MLS_PROJECTED_TABLE_FILE,
        EXTRA_PROJECTED_TABLE_FILE,
        CUP_PROJECTED_TABLE_FILE,
    ]
    for path in csv_sources:
        if not os.path.exists(path):
            continue
        try:
            df = pd.read_csv(path, dtype=str, encoding="utf-8")
        except Exception:
            continue
        if "competition" not in df.columns:
            continue
        mask = df["competition"].astype(str).str.strip() == comp_name
        sub = df[mask]
        if sub.empty:
            continue
        if "team" in sub.columns:
            teams.update(sub["team"].dropna().astype(str).str.strip())
        elif "home_team" in sub.columns:
            teams.update(sub["home_team"].dropna().astype(str).str.strip())
        if "away_team" in sub.columns:
            teams.update(sub["away_team"].dropna().astype(str).str.strip())

    if not teams:
        return None

    now_utc = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
    entries = []
    for pos, team in enumerate(sorted(teams), start=1):
        entries.append({
            "position": pos, "team": team,
            "P": 0, "W": 0, "D": 0, "L": 0,
            "GF": 0, "GA": 0, "GD": 0, "Pts": 0,
        })
    return {
        "competition": comp_name,
        "updated_at": now_utc,
        "groups": [{"name": "Overall", "entries": entries}],
        "source": "placeholder",
    }


@app.get("/api/real-tables")
@_cached_response(ttl=CACHE_TTL_DEFAULT)
def api_real_tables():
    """Return real league tables computed from live-score history.

    Supports standard leagues, group-stage (World Cup, UCL),
    MLS conferences, Belgian 2-phase, Scottish Premiership split,
    and UEFA league-phase competitions.

    Query params:
        competition  -- optional, fetch a specific competition only
                        (e.g. "England/Premier League", "FIFA/World Cup")
                        If omitted, returns tables for all known competitions.
    """
    comp_filter = request.args.get("competition", "").strip()
    force_refresh = request.args.get("refresh", "").strip().lower() in ("1", "true")

    if comp_filter:
        if comp_filter not in LIVE_SCORE_COMPETITIONS:
            return jsonify({"ok": False, "error": f"Unknown competition: {comp_filter}"}), 400
        if force_refresh:
            _clear_standings_cache(comp_filter)
            _clear_leaders_cache(comp_filter)
        # Try persisted cache first
        persisted = _load_json_payload(REAL_TABLES_PERSIST_FILE)
        if isinstance(persisted, dict) and comp_filter in persisted:
            return jsonify({"ok": True, "table": persisted[comp_filter]})
        table = _compute_standings_from_history(comp_filter)
        if table is not None:
            return jsonify({"ok": True, "table": table})
        fallback = _build_fallback_standings(comp_filter)
        return jsonify({"ok": True, "table": fallback})

    results = {}
    now_utc = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
    # Try persisted standings cache first (built by the daily pipeline)
    persisted = _load_json_payload(REAL_TABLES_PERSIST_FILE)
    if isinstance(persisted, dict):
        for comp_name in LIVE_SCORE_COMPETITIONS:
            cached = persisted.get(comp_name)
            if cached and cached.get("groups"):
                results[comp_name] = cached
                continue
            if force_refresh:
                _clear_standings_cache(comp_name)
                _clear_leaders_cache(comp_name)
            table = _compute_standings_from_history(comp_name)
            if table is not None:
                results[comp_name] = table
            else:
                fallback = _build_fallback_standings(comp_name)
                if fallback is not None:
                    results[comp_name] = fallback
                else:
                    results[comp_name] = {
                        "competition": comp_name,
                        "updated_at": now_utc,
                        "groups": [{"name": "Overall", "entries": []}],
                        "source": "placeholder",
                    }
    else:
        for comp_name in LIVE_SCORE_COMPETITIONS:
            if force_refresh:
                _clear_standings_cache(comp_name)
                _clear_leaders_cache(comp_name)
            table = _compute_standings_from_history(comp_name)
            if table is not None:
                results[comp_name] = table
            else:
                fallback = _build_fallback_standings(comp_name)
                if fallback is not None:
                    results[comp_name] = fallback
                else:
                    results[comp_name] = {
                        "competition": comp_name,
                        "updated_at": now_utc,
                        "groups": [{"name": "Overall", "entries": []}],
                        "source": "placeholder",
                    }
    return jsonify({"ok": True, "tables": results, "total": len(results)})


@app.get("/api/tournament/<key>")
@_cached_response(ttl=CACHE_TTL_DEFAULT)
def api_tournament(key):
    """Alias for competition-data keyed by short tournament slug (mobile app)."""
    comp = _TOURNAMENT_KEY_TO_COMP.get(str(key).strip().lower())
    if not comp:
        return jsonify({"ok": False, "error": f"Unknown tournament: {key}"}), 404
    if comp == "FIFA/World Cup":
        return api_world_cup()
    from urllib.parse import quote
    with app.test_request_context(f"/api/competition-data?competition={quote(comp, safe='')}"):
        return api_competition_data()


@app.get("/api/competition-data")
@_cached_response(ttl=CACHE_TTL_DEFAULT)
def api_competition_data():
    """Return full competition data in World Cup format for any competition.

    Works for *all* competitions tracked by the system (leagues, cups,
    World Cup).  The response mirrors ``/api/world-cup``:

    * ``knockout`` — ``{stage_key: [matches]}}`` with predicted winners
      from the projection / simulation.
    * ``odds_knockout`` — same topology, each match's ``winner`` is the
      team with higher ``prob_home`` / ``prob_away``.
    * ``real_knockout`` — winners only from completed (``post``) games;
      unplayed matches show both teams but ``winner: null``.
    * ``group_tables`` / ``table`` — group / league phase standings when
      applicable.
    * ``champion`` — aggregate most-likely champion from simulation.
    * ``simulations_run`` — how many tournament simulations were aggregated.
    * ``winner_probabilities`` — per-team champion probability map.
    * ``cup_format``, ``knockout_rounds`` — cup/stage metadata.

    For regular leagues (no knockout bracket) the ``knockout`` / odds /
    real fields are omitted and only ``table`` is returned.

    Query params:
        competition  -- required, e.g. "UEFA/Champions League",
                        "England/Premier League", "FIFA/World Cup"
    """
    comp = request.args.get("competition", "").strip()
    if not comp:
        return jsonify({"ok": False, "error": "Missing 'competition' parameter"}), 400
    if comp not in LIVE_SCORE_COMPETITIONS:
        return jsonify({"ok": False, "error": f"Unknown competition: {comp}"}), 400

    # ── Special case: World Cup uses its dedicated projection file ──
    if comp == "FIFA/World Cup":
        return api_world_cup()

    # ── Gather basic building blocks ──────────────────────────────
    table = _compute_standings_from_history(comp)
    cup_format = _CUP_FORMATS.get(comp)
    ko_framework = _build_knockout_framework(comp)

    result = {
        "ok": True,
        "competition": comp,
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
    }

    if table is not None:
        result["table"] = table
    if cup_format:
        result["cup_format"] = cup_format
    if ko_framework:
        result["knockout_rounds"] = ko_framework

    # ── Simulation / champion data from projected cup brackets ────
    bracket_data = _load_json_payload(CUP_PROJECTED_BRACKET_FILE)
    if isinstance(bracket_data, dict):
        comps = bracket_data.get("competitions", bracket_data)
        if isinstance(comps, dict) and comp in comps:
            entry = comps[comp]
            if isinstance(entry, dict):
                for key in ("champion", "simulations_run", "winner_probabilities", "sim_index"):
                    if key in entry:
                        result[key] = entry[key]
                if "generated_at_utc" in bracket_data:
                    result["generated_at_utc"] = bracket_data["generated_at_utc"]

    # ── Knockout bracket (WC-style) ──────────────────────────────
    # Build the three knockout structures using the same logic as
    # /api/cup-bracket but without needing a separate request.
    matches = []

    # Completed games from history
    history = _load_live_score_history()
    seen_ids = set()
    for g in history:
        if g.get("competition") == comp:
            mid = g.get("match_id", "")
            if mid:
                seen_ids.add(mid)
            matches.append(g)

    # In-progress / finished today from live scores
    with _live_scores_lock:
        current = _live_scores.get(comp, {}).get("games", [])
    for g in current:
        mid = g.get("match_id", "")
        if mid not in seen_ids:
            if mid:
                seen_ids.add(mid)
            matches.append(g)

    # Upcoming from projected cup bracket
    if isinstance(bracket_data, dict):
        comps = bracket_data.get("competitions", bracket_data)
        if isinstance(comps, dict) and comp in comps:
            entry = comps[comp]
            if isinstance(entry, dict):
                rounds_list = entry.get("rounds") or []
                for rnd in rounds_list:
                    rnd_name = rnd.get("name", "")
                    for m in rnd.get("matches", []):
                        hm = str(m.get("home_team", "") or "")
                        aw = str(m.get("away_team", "") or "")
                        if not hm or not aw:
                            continue
                        matches.append({
                            "home_team": hm,
                            "away_team": aw,
                            "home_score": None,
                            "away_score": None,
                            "status": "pre",
                            "kickoff_utc": _utc_to_et(str(m.get("match_datetime_utc", "") or "")),
                            "round": rnd_name,
                            "competition": comp,
                            "match_id": str(m.get("match_id", "") or ""),
                        })

    if not matches:
        if comp in _CUP_FORMATS:
            result = _enrich_tournament_payload(comp, result)
        return jsonify(result)

    # Enrich with odds from cup predictions CSV
    odds_index = {}
    try:
        odds_df = pd.read_csv(CUP_UPCOMING_FILE)
        if not odds_df.empty and all(c in odds_df.columns for c in ("home_team", "away_team", "prob_home", "prob_draw", "prob_away")):
            for _, row in odds_df.iterrows():
                key = (str(row["home_team"]).strip().lower(), str(row["away_team"]).strip().lower())
                odds_index[key] = {
                    "prob_home": _safe_float(row["prob_home"], None),
                    "prob_draw": _safe_float(row["prob_draw"], None),
                    "prob_away": _safe_float(row["prob_away"], None),
                }
    except Exception:
        pass

    for g in matches:
        rnd = g.get("round", "") or "Match"
        order = g.get("round_order", 0)
        if not isinstance(order, (int, float)):
            try:
                order = int(order)
            except (ValueError, TypeError):
                order = 0
        g["round_order"] = order
        g["round"] = rnd

        if g.get("status") == "post":
            hs = g.get("home_score")
            aws = g.get("away_score")
            if hs is not None and aws is not None:
                if hs > aws:
                    g["winner"] = g.get("home_team", "")
                elif aws > hs:
                    g["winner"] = g.get("away_team", "")

        hm_name = str(g.get("home_team", "")).strip().lower()
        aw_name = str(g.get("away_team", "")).strip().lower()
        odds = odds_index.get((hm_name, aw_name)) or odds_index.get((aw_name, hm_name), {})
        g["prob_home"] = odds.get("prob_home")
        g["prob_draw"] = odds.get("prob_draw")
        g["prob_away"] = odds.get("prob_away")

    knockout, odds_knockout, real_knockout = _build_knockout_wc_format(matches)
    if cup_format and cup_format.get("two_leg_rounds"):
        knockout = _expand_two_leg_knockout(knockout, cup_format["two_leg_rounds"])
        odds_knockout = _expand_two_leg_knockout(odds_knockout, cup_format["two_leg_rounds"])
        real_knockout = _expand_two_leg_knockout(real_knockout, cup_format["two_leg_rounds"])
    result["knockout"] = knockout
    result["odds_knockout"] = odds_knockout
    result["real_knockout"] = real_knockout

    if comp in _CUP_FORMATS:
        result = _enrich_tournament_payload(comp, result)
    return jsonify(result)


@app.get("/api/league-tables")
@_cached_response(ttl=CACHE_TTL_LONG)
def api_league_tables():
    """Return projected league tables (and MLS playoff bracket when requested).

    Includes a ``last_prediction_refresh`` field with the file mtime in UTC.
    Also includes all scheduled fixtures (``fixtures``) for the requested mode,
    grouped by competition, so the frontend can show the full season schedule
    for each league alongside the projected standings.
    """
    mode = str(request.args.get("mode", "global")).strip().lower()

    # If current_season_teams.json exists, use it instead of stale CSV data.
    season_data = _load_current_season_tables()

    if mode == "mls":
        if season_data:
            mls_leagues = [c for c in season_data.get("leagues", [])
                           if "MLS" in c or "United States" in c]
            data = {
                "leagues": mls_leagues,
                "tables": {c: season_data["tables"][c]
                           for c in mls_leagues if c in season_data.get("tables", {})},
            }
        else:
            csv_path = MLS_PROJECTED_TABLE_FILE
            data = _load_projected_tables(csv_path)
        bracket = _load_json_payload(MLS_PROJECTED_BRACKET_FILE)
        data["last_prediction_refresh"] = _file_mtime_utc(MLS_PROJECTED_TABLE_FILE) if not season_data else None
        fixtures = _load_all_fixtures_by_competition(MLS_UPCOMING_FILE)
        return jsonify({"ok": True, **data, "bracket": bracket, "fixtures": fixtures})
    if mode == "cups":
        csv_path = CUP_PROJECTED_TABLE_FILE
        data = _load_projected_tables(csv_path)
        if not data.get("leagues"):
            data["leagues"] = list(_CUP_FORMATS)
        brackets = _load_json_payload(CUP_PROJECTED_BRACKET_FILE)
        data["last_prediction_refresh"] = _file_mtime_utc(csv_path)
        known_cups = set(data.get("leagues") or [])
        for comp_name in _CUP_FORMATS:
            if comp_name not in known_cups:
                known_cups.add(comp_name)
        data["leagues"] = sorted(known_cups)
        cup_formats = {}
        if isinstance(brackets, dict):
            comps = brackets.get("competitions", brackets)
            if isinstance(comps, dict):
                for comp_name in comps:
                    fmt = _CUP_FORMATS.get(comp_name)
                    if fmt:
                        cup_formats[comp_name] = fmt
        for comp_name in data.get("leagues") or []:
            if comp_name not in cup_formats:
                fmt = _CUP_FORMATS.get(comp_name)
                if fmt:
                    cup_formats[comp_name] = fmt
        odds_bracket = _compute_odds_bracket()
        knockout_frameworks = {}
        for comp_name in list(cup_formats.keys()) + (data.get("leagues") or []):
            kf = _build_knockout_framework(comp_name)
            if kf:
                knockout_frameworks[comp_name] = kf
        fixtures = _load_all_fixtures_by_competition(CUP_UPCOMING_FILE)
        return jsonify({
            "ok": True, **data,
            "cup_brackets": brackets, "cup_formats": cup_formats,
            "odds_bracket": odds_bracket,
            "knockout_frameworks": knockout_frameworks,
            "fixtures": fixtures,
        })
    if mode == "extra":
        if season_data:
            data = season_data
        else:
            csv_path = EXTRA_PROJECTED_TABLE_FILE
            data = _load_projected_tables(csv_path)
        data["last_prediction_refresh"] = None
        fixtures = _load_all_fixtures_by_competition(EXTRA_UPCOMING_FILE)
        return jsonify({"ok": True, **data, "fixtures": fixtures})
    else:
        if season_data:
            data = season_data
        else:
            csv_path = GLOBAL_PROJECTED_TABLE_FILE
            data = _load_projected_tables(csv_path)
        data["last_prediction_refresh"] = None
        fixtures = _load_all_fixtures_by_competition(GLOBAL_UPCOMING_FILE)
    return jsonify({"ok": True, **data, "fixtures": fixtures})


@app.get("/api/league-data/<path:competition>")
@_cached_response(ttl=CACHE_TTL_LONG)
def api_league_data(competition):
    """Return consolidated data for a single league / cup / competition.

    Combines projected table, position odds, winners odds, real table,
    and upcoming fixtures into one response.

    .. code-block:: json

        {"ok": true, "competition": "...",
         "predicted_table": [...],
         "position_odds": {"simple": {pos: [{team, pct}, ...]},
                           "detailed": [{team, odds: {pos: pct, ...}}, ...]},
         "winners_odds": [{team, win_league_pct, top4_pct, ...}, ...],
         "real_table": {"groups": [...], "source": "real"},
         "fixtures": [...]}
    """
    comp = competition.strip()

    # ── 1. Find projected table from any CSV source ───────────────
    table_sources = [
        ("global", GLOBAL_PROJECTED_TABLE_FILE),
        ("mls", MLS_PROJECTED_TABLE_FILE),
        ("extra", EXTRA_PROJECTED_TABLE_FILE),
        ("cups", CUP_PROJECTED_TABLE_FILE),
    ]
    predicted_table = []
    position_odds_simple = {}
    position_odds_detailed = []
    winners_odds = []
    found_source = None

    for source_name, csv_path in table_sources:
        proj = _load_projected_tables(csv_path)
        if comp in proj.get("tables", {}):
            found_source = source_name
            comp_table = proj["tables"][comp]
            predicted_table = comp_table

            # Winners odds — all teams sorted by win_league_pct desc
            winners = []
            for row in comp_table:
                winners.append({
                    "team": row.get("team", ""),
                    "win_league_pct": row.get("win_league_pct"),
                    "top4_pct": row.get("top4_pct"),
                    "bottom3_pct": row.get("bottom3_pct"),
                    "most_likely_position": row.get("most_likely_position"),
                    "most_likely_position_pct": row.get("most_likely_position_pct"),
                })
            winners.sort(key=lambda x: x.get("win_league_pct") or 0, reverse=True)
            winners_odds = winners

            # Position odds — simple (per-position team list) + detailed (per-team)
            pos_simple = {}
            pos_detailed = []
            for row in comp_table:
                team = row.get("team", "")
                raw = row.get("position_odds")
                if raw and isinstance(raw, dict):
                    entry = {"team": team, "odds": {}}
                    for pos_str, pct in raw.items():
                        pct_f = float(pct) if pct is not None else 0.0
                        entry["odds"][str(pos_str)] = pct_f
                        if str(pos_str) not in pos_simple:
                            pos_simple[str(pos_str)] = []
                        pos_simple[str(pos_str)].append({"team": team, "pct": pct_f})
                    pos_detailed.append(entry)
            # Sort each position's teams by pct descending
            for ps in pos_simple:
                pos_simple[ps].sort(key=lambda x: x["pct"], reverse=True)
            position_odds_simple = dict(sorted(pos_simple.items(), key=lambda kv: int(kv[0]) if kv[0].isdigit() else 999))
            position_odds_detailed = pos_detailed
            break

    # If no projected table found in CSVs, fall back to league roster
    if not predicted_table:
        league_teams = _load_league_teams()
        roster = league_teams.get(comp)
        if roster:
            predicted_table = []
            winners_odds = []
            for pos, team in enumerate(sorted(roster), start=1):
                entry = {
                    "position": pos, "team": team,
                    "P": 0, "W": 0, "D": 0, "L": 0,
                    "GF": 0, "GA": 0, "GD": 0, "Pts": 0,
                    "PlayedReal": 0, "PlayedPred": 0,
                    "win_league_pct": 0.0, "top4_pct": 0.0, "bottom3_pct": 0.0,
                    "most_likely_position": 0, "most_likely_position_pct": 0.0,
                    "position_odds": {}, "sim_runs": 0,
                }
                predicted_table.append(entry)
                winners_odds.append({
                    "team": team,
                    "win_league_pct": 0.0, "top4_pct": 0.0, "bottom3_pct": 0.0,
                    "most_likely_position": 0, "most_likely_position_pct": 0.0,
                })

    # ── 2. Real table from live-score history ─────────────────────
    real_table = _compute_standings_from_history(comp)

    # ── 3. Upcoming fixtures with prediction odds ────────────────
    upcoming_sources = [
        GLOBAL_UPCOMING_FILE,
        MLS_UPCOMING_FILE,
        EXTRA_UPCOMING_FILE,
        CUP_UPCOMING_FILE,
    ]
    fixtures = []
    for csv_path in upcoming_sources:
        try:
            rows, _, _ = _load_upcoming_rows(csv_path, date_range="all")
            comp_fixtures = [r for r in rows if r.get("competition") == comp]
            if comp_fixtures:
                fixtures = comp_fixtures
                break
        except Exception:
            continue

    payload = {
        "ok": True,
        "competition": comp,
        "predicted_table": predicted_table,
        "position_odds": {
            "simple": position_odds_simple,
            "detailed": position_odds_detailed,
        },
        "winners_odds": winners_odds,
        "real_table": real_table,
        "fixtures": fixtures,
    }
    payload = _enrich_league_data_cup_fields(comp, payload)
    return jsonify(payload)


@app.get("/api/stats")
def api_stats():
    """Return overall site stats: accuracy, league count, last refresh time."""
    global _last_pipeline_run
    try:
        rows, stats, league_stats = _load_upcoming_rows(GLOBAL_UPCOMING_FILE, "global")
        accuracy_pct = (stats or {}).get("accuracy_pct", 0.0)
    except Exception:
        accuracy_pct = 0.0
    refreshed_at = _last_pipeline_run.isoformat() if _last_pipeline_run else None
    return jsonify({
        "ok": True,
        "accuracy_pct": accuracy_pct,
        "league_count": 18,
        "refreshed_at": refreshed_at,
    })


@app.get("/api/league-leaders")
@_cached_response(ttl=CACHE_TTL_LONG)
def api_league_leaders():
    """Return predicted and real (live) leaders for every league and cup.

    Response:

    .. code-block:: json

        {"ok": true, "leagues": [{"competition": "...",
          "predicted_winner": "...", "predicted_winner_odds": 0.0,
          "current_leader": "...", "leader_source": "real"|"predicted"},
          ...],
         "cups": [{"competition": "...",
          "predicted_winner": "...", "predicted_winner_odds": 0.0}, ...]}
    """
    leagues = []
    cups = []

    # Competition names that are aliases — skip to avoid duplicates
    _COMPETITION_ALIASES = {
        "Europe/Champions League", "Europe/Europa League", "Europe/Conference League",
    }

    # ── Predicted winners from projected table CSVs ───────────────
    table_sources = [
        ("global", GLOBAL_PROJECTED_TABLE_FILE),
        ("mls", MLS_PROJECTED_TABLE_FILE),
        ("extra", EXTRA_PROJECTED_TABLE_FILE),
        ("cups", CUP_PROJECTED_TABLE_FILE),
    ]

    # Collect MLS sub-competition data for nested entry
    mls_supporters = {}
    mls_east = {}
    mls_west = {}

    for source_mode, csv_path in table_sources:
        proj = _load_projected_tables(csv_path)
        comp_list = proj.get("leagues") or []
        for comp_name in comp_list:
            # MLS sub-competitions — collect separately
            if comp_name.startswith("United States/MLS"):
                comp_tbl = proj.get("tables", {}).get(comp_name, [])
                pos1 = next((r for r in comp_tbl if r.get("position") == 1), None)
                if pos1:
                    if "Supporters Shield" in comp_name:
                        mls_supporters = pos1
                    elif "Eastern Conference" in comp_name:
                        mls_east = pos1
                    elif "Western Conference" in comp_name:
                        mls_west = pos1
                continue
            if comp_name in _COMPETITION_ALIASES:
                continue
            comp_tbl = proj.get("tables", {}).get(comp_name, [])
            predicted = None
            for row in comp_tbl:
                if row.get("position") == 1:
                    predicted = {
                        "winner": row.get("team", ""),
                        "odds": row.get("win_league_pct"),
                    }
                    break
            if not predicted:
                if source_mode == "cups":
                    if comp_name not in _CUP_FORMATS and comp_name != "FIFA/World Cup":
                        continue
                else:
                    continue
            entry = {
                "competition": comp_name,
                "predicted_winner": predicted["winner"] if predicted else "—",
                "predicted_winner_odds": round(predicted["odds"], 1) if predicted and predicted["odds"] is not None else None,
            }
            if source_mode == "cups":
                cups.append(entry)
            else:
                leagues.append(entry)

    # Add unified MLS entry
    mls_bracket = _load_json_payload(MLS_PROJECTED_BRACKET_FILE)
    mls_cup_winner = None
    mls_cup_odds = None
    if isinstance(mls_bracket, dict):
        cup_data = mls_bracket.get("mls_cup") or {}
        mls_cup_winner = cup_data.get("winner")
    mls_entry = {
        "competition": "United States/MLS",
        "predicted_winner": (mls_supporters.get("team") if mls_supporters else None) or "—",
        "predicted_winner_odds": round(mls_supporters.get("win_league_pct"), 1) if mls_supporters and mls_supporters.get("win_league_pct") is not None else None,
        "east_leader": (mls_east.get("team") if mls_east else None) or None,
        "west_leader": (mls_west.get("team") if mls_west else None) or None,
        "mls_cup_winner": mls_cup_winner or None,
    }
    leagues.append(mls_entry)

    # ── Cup champions from cup brackets JSON (simulation data) ────
    bracket_data = _load_json_payload(CUP_PROJECTED_BRACKET_FILE)
    if isinstance(bracket_data, dict):
        comps = bracket_data.get("competitions", bracket_data)
        if isinstance(comps, dict):
            for comp_name, comp_entry in comps.items():
                if not isinstance(comp_entry, dict):
                    continue
                if comp_name in _COMPETITION_ALIASES:
                    continue
                champion = comp_entry.get("champion")
                winner_probs = comp_entry.get("winner_probabilities") or {}
                prob = winner_probs.get(champion, None) if champion else None
                # Avoid duplicating entries already from cup table CSV
                if not any(c["competition"] == comp_name for c in cups):
                    cups.append({
                        "competition": comp_name,
                        "predicted_winner": champion or "—",
                        "predicted_winner_odds": round(prob * 100, 1) if prob is not None else None,
                    })
                else:
                    # Update odds with simulation data when available
                    if prob is not None:
                        for c in cups:
                            if c["competition"] == comp_name and champion:
                                c["predicted_winner"] = champion
                                c["predicted_winner_odds"] = round(prob * 100, 1)

    # Also add World Cup as a cup
    wc_file = os.path.join(PROJECT_DIR, "Data", "Predictions", "world_cup_projection.json")
    if os.path.exists(wc_file):
        try:
            with open(wc_file, "r") as f:
                wc = json.load(f)
            wc_champion = wc.get("champion")
            wc_probs = wc.get("winner_probabilities") or {}
            wc_prob = wc_probs.get(wc_champion, None) if wc_champion else None
            if not any(c["competition"] == "FIFA/World Cup" for c in cups):
                cups.append({
                    "competition": "FIFA/World Cup",
                    "predicted_winner": wc_champion or "—",
                    "predicted_winner_odds": round(wc_prob * 100, 1) if wc_prob is not None else None,
                })
        except Exception:
            pass

    # ── Include all known competitions with predictions or real tables ──
    cup_set = set(c["competition"] for c in cups)
    league_names = set(e["competition"] for e in leagues)

    # Add any cup competitions from LIVE_SCORE_COMPETITIONS not yet listed
    for comp_name in LIVE_SCORE_COMPETITIONS:
        if comp_name in cup_set or comp_name in league_names:
            continue
        if comp_name in _COMPETITION_ALIASES:
            continue
        if comp_name in _CUP_FORMATS:
            cups.append({
                "competition": comp_name,
                "predicted_winner": "—",
                "predicted_winner_odds": None,
            })
        else:
            leagues.append({
                "competition": comp_name,
                "predicted_winner": "—",
                "predicted_winner_odds": None,
            })

    # ── Real leaders from live score history / ESPN ──────────────
    cup_set = set(c["competition"] for c in cups)
    for entry in leagues:
        comp = entry["competition"]
        if comp in cup_set:
            continue
        # MLS real leaders — read from history for East/West conferences
        if comp == "United States/MLS":
            east_real = _compute_standings_from_history("United States/MLS - Eastern Conference")
            west_real = _compute_standings_from_history("United States/MLS - Western Conference")
            if east_real and isinstance(east_real, dict):
                for g in (east_real.get("groups") or []):
                    if g.get("entries"):
                        entry["east_leader"] = g["entries"][0].get("team", "")
                        break
            if west_real and isinstance(west_real, dict):
                for g in (west_real.get("groups") or []):
                    if g.get("entries"):
                        entry["west_leader"] = g["entries"][0].get("team", "")
                        break
            overall_real = _compute_standings_from_history("United States/MLS - Supporters Shield Table")
            if overall_real and isinstance(overall_real, dict):
                for g in (overall_real.get("groups") or []):
                    if g.get("entries"):
                        entry["current_leader"] = g["entries"][0].get("team", "")
                        entry["leader_source"] = "real"
                        break
            if "leader_source" not in entry:
                entry["current_leader"] = entry.get("predicted_winner") if entry.get("predicted_winner") and entry["predicted_winner"] != "—" else None
                entry["leader_source"] = "predicted"
            continue
        real = _compute_standings_from_history(comp)
        if real and isinstance(real, dict):
            for g in (real.get("groups") or []):
                if g.get("entries"):
                    entry["current_leader"] = g["entries"][0].get("team", "")
                    entry["leader_source"] = "real"
                    break
            else:
                if entry.get("predicted_winner") and entry["predicted_winner"] != "—":
                    entry["current_leader"] = entry["predicted_winner"]
                    entry["leader_source"] = "predicted"
                else:
                    entry["current_leader"] = None
                    entry["leader_source"] = "predicted"
        else:
            if entry.get("predicted_winner") and entry["predicted_winner"] != "—":
                entry["current_leader"] = entry["predicted_winner"]
                entry["leader_source"] = "predicted"
            else:
                entry["current_leader"] = None
                entry["leader_source"] = "predicted"

    return jsonify({
        "ok": True,
        "leagues": leagues,
        "cups": cups,
    })


@app.post("/api/feedback")
def api_feedback():
    """Persist user feedback to a local text file."""
    payload = request.get_json(silent=True) or request.form or {}
    feedback_text = str(payload.get("feedback", "")).strip()
    if not feedback_text:
        return jsonify({"ok": False, "error": "Feedback cannot be empty."}), 400
    if len(feedback_text) > 5000:
        return jsonify({"ok": False, "error": "Feedback is too long (max 5000 characters)."}), 400

    timestamp = datetime.now(ZoneInfo("America/New_York")).isoformat()
    remote_addr = request.headers.get("X-Forwarded-For") or request.remote_addr or "unknown"
    user_agent = request.headers.get("User-Agent", "unknown")
    entry = (
        f"[{timestamp}] ip={remote_addr}\n"
        f"user_agent={user_agent}\n"
        f"feedback={feedback_text}\n"
        "-----\n"
    )
    try:
        os.makedirs(FEEDBACK_DIR, exist_ok=True)
        with _feedback_lock:
            with open(FEEDBACK_FILE, "a", encoding="utf-8") as fh:
                fh.write(entry)
    except Exception as exc:
        return jsonify({"ok": False, "error": "Failed to save feedback"}), 500
    return jsonify({"ok": True})


@app.get("/tactics")
def tactics():
    """Render the tactics whiteboard page."""
    return render_template("tactics.html")


@app.get("/players")
def players():
    """Render the players/top scorers page."""
    return render_template("players.html")


@app.get("/api/scorers")
def api_scorers():
    """Return current season top scorers by competition."""
    if not os.path.exists(TOP_SCORERS_FILE):
        return jsonify({"ok": False, "error": "Scorers data not available", "competitions": {}}), 404
    
    try:
        with open(TOP_SCORERS_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except Exception as exc:
        return jsonify({"ok": False, "error": "Could not load scorers", "competitions": {}}), 500
    
    competitions = data.get("competitions", {})
    last_updated = data.get("last_updated_utc", "Unknown")
    
    return jsonify({
        "ok": True,
        "last_updated_utc": last_updated,
        "competitions": competitions,
        "available_leagues": sorted(competitions.keys()),
    })


@app.get("/graphics/<path:filename>")
def serve_graphic(filename):
    """Serve assets from Website/graphics for logos and other static artwork."""
    return send_from_directory(GRAPHICS_DIR, filename)


if __name__ == "__main__":
    import argparse
    import socket

    parser = argparse.ArgumentParser()
    parser.add_argument("--host", default="0.0.0.0", help="Host to bind to")
    parser.add_argument("--port", type=int, default=5000, help="Port to bind to")
    parser.add_argument(
        "--debug",
        action="store_true",
        help="Enable Flask debug mode (with auto-reload; spawns a reloader process)",
    )
    parser.add_argument(
        "--reload",
        action="store_true",
        help="Enable Werkzeug file-change reloader (requires --debug)",
    )
    args = parser.parse_args()

    if args.reload and not args.debug:
        raise SystemExit("--reload requires --debug")

    use_reloader = bool(args.debug and args.reload)

    if args.host == "0.0.0.0":
        try:
            s = socket.socket(socket.AF_INET, socket.sock_dgram)
            s.connect(("8.8.8.8", 80))
            ip = s.getsockname()[0]
            s.close()
            print(f"\n * Connect from other devices at: http://{ip}:{args.port}\n")
        except Exception:
            pass

    # Warn when auth env vars are missing
    if not REFRESH_API_TOKEN:
        print("[startup] WARNING: REFRESH_API_TOKEN not set — /api/refresh is unprotected!")
    if not NOTIFICATIONS_API_KEY:
        print("[startup] WARNING: NOTIFICATIONS_API_KEY not set — notification endpoints are unprotected!")
    if not DEBUG_API_KEY and not REFRESH_API_TOKEN:
        print("[startup] WARNING: DEBUG_API_KEY and REFRESH_API_TOKEN both unset — debug endpoints are disabled (all return 401)!")

    start_live_score_poller()

    # Start APNs background worker (does nothing if env vars not set)
    _start_apns_worker()

    app.run(
        host=args.host,
        port=args.port,
        debug=args.debug,
        use_reloader=use_reloader,
    )
